CREATE OR REPLACE FUNCTION makestuffgo.count_recent_audits(p_days integer)
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE
  v_count integer;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM makestuffgo.feedback_audit a
  WHERE a.created_at > now() - (p_days || ' days')::interval;
  RETURN v_count;
END
$$;
